    {"filter": "datum.rank <= 10"}
  ],

  "mark":"bar",
  "encoding":
  {
    "x":{
      "field":"country",
      "type":"nominal" ,
      "sort": {"field": "y", "order": "ascending"}
      },
    "y":{

      "aggregate":"count",
      "type":"quantitative"

